//! 各平台的隐私标记常量。命中任意一个就不读正文（concealed = true）。

/// Wisp 自己写入剪贴板时附加的私有类型 / 格式名
pub const WISP_MARKER: &str = "io.github.yzlltyyh.wisp.marker";

/// macOS：NSPasteboard 类型（nspasteboard.org 约定 + 各密码管理器私有类型；部分需核实）
pub const MACOS_CONCEALED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
    "net.antelle.keeweb",
];

/// Windows：注册的剪贴板格式名。前两项只要存在即命中；后两项值为 0 时命中
pub const WINDOWS_EXCLUDE_FORMATS: &[&str] = &[
    "ExcludeClipboardContentFromMonitorProcessing",
    "Clipboard Viewer Ignore",
];

/// Windows：值为 0（DWORD）时视为隐私内容的格式名
pub const WINDOWS_ZERO_MEANS_PRIVATE_FORMATS: &[&str] = &["CanIncludeInClipboardHistory", "CanUploadToCloudClipboard"];

/// Linux（KDE）：密码管理器提示的 MIME 类型及其取值
pub const LINUX_PASSWORD_HINT_MIME: &str = "x-kde-passwordManagerHint";
/// Linux（KDE）：命中的取值
pub const LINUX_PASSWORD_HINT_SECRET: &str = "secret";

/// macOS：剪贴板的类型列表里是否有任一隐私标记（先于读取正文调用）
pub fn macos_is_concealed<'a>(types: impl IntoIterator<Item = &'a str>) -> bool {
    types.into_iter().any(|t| MACOS_CONCEALED_TYPES.contains(&t))
}

/// 剪贴板是否带有 Wisp 自己的私有标记
pub fn has_wisp_marker<'a>(types: impl IntoIterator<Item = &'a str>) -> bool {
    types.into_iter().any(|t| t == WISP_MARKER)
}

/// Windows：某个已注册格式是否表示隐私内容。`dword` 是该格式数据的前 4 字节（小端 DWORD；读不到时为 None）。
/// [`WINDOWS_EXCLUDE_FORMATS`] 只要存在即命中；[`WINDOWS_ZERO_MEANS_PRIVATE_FORMATS`] 值为 0 时命中，
/// 读不到值时按安全优先视为命中
pub fn windows_format_is_private(format_name: &str, dword: Option<u32>) -> bool {
    if WINDOWS_EXCLUDE_FORMATS
        .iter()
        .any(|f| f.eq_ignore_ascii_case(format_name))
    {
        return true;
    }
    if WINDOWS_ZERO_MEANS_PRIVATE_FORMATS
        .iter()
        .any(|f| f.eq_ignore_ascii_case(format_name))
    {
        return dword.is_none_or(|v| v == 0);
    }
    false
}

/// Linux（KDE）：某个 MIME 类型及其内容是否是密码管理器提示（`x-kde-passwordManagerHint` = `secret`）
pub fn linux_is_password_hint(mime: &str, value: &[u8]) -> bool {
    mime == LINUX_PASSWORD_HINT_MIME
        && String::from_utf8_lossy(value)
            .trim_matches(|c: char| c.is_whitespace() || c == '\0')
            .eq_ignore_ascii_case(LINUX_PASSWORD_HINT_SECRET)
}
